const $=s=>document.querySelector(s);
const tabs=[['home','Home / Manifesto'],['files','Richard Night Files'],['sovereignty','Sovereignty Experiment'],['circuit','Circuit Economics'],['street','Street Intelligence'],['reborn','Night City Reborn']];
const sources={history:'https://cyberpunk.fandom.com/wiki/Night_City',districts:'https://www.cyberpunk.net/en/news/50110/your-trip-to-night-city-best-spots-for-street-photography',gangs:'https://www.pcgamer.com/cyberpunk-2077-gangs-factions/',ostrom:'https://www.nobelprize.org/uploads/2018/06/press-7.pdf',moniac:'https://blog.sciencemuseum.org.uk/back-to-the-future-of-computing/'};
const tag=(type,label=type)=>`<span class="tag ${type}">${label}</span>`;
const intro=(type,kicker,title,body)=>`<div class="intro">${tag(type)}<div class="eyebrow" style="margin-top:22px">${kicker}</div><h1>${title}</h1><p class="lead">${body}</p></div>`;
let allocations=[25,25,25,25], shock=0, circuit={damping:.35,feedback:1,shock:1}, timelineIndex=0, loreFilter='all', loreSearch='', extended=false, plan=[true,true,false,false,false,false];
const planItems=[['Co-op housing',25,'Shared land ownership; requires fair access rules.'],['Public transit',25,'Frequent shared mobility; requires operating funds.'],['Microgrid',20,'Local energy backup; requires maintenance expertise.'],['Open network',10,'Community connectivity; requires privacy safeguards.'],['Civic assembly',10,'Resident oversight; requires time and representation.'],['Cooling commons',15,'Shade and shared green space; requires water and upkeep.']];
function cityArt(){let buildings='';for(let i=0;i<29;i++){const x=i*23-20,h=70+(i*67%220),w=15+(i*13%28);buildings+=`<rect x="${x}" y="${445-h}" width="${w}" height="${h}" fill="${i%3?'#121321':'#251b30'}" stroke="#71344c" stroke-width=".7"/>`;for(let j=0;j<Math.floor(h/19);j++){buildings+=`<rect x="${x+4}" y="${451-h+j*18}" width="${i%2?3:7}" height="3" fill="${j%4?'#ef558e':'#67e9e2'}" opacity="${.3+(j%3)*.2}"/>`;}}return `<div class="city-art" role="img" aria-label="Original abstract neon skyline: a dark city under a fragmented pink sun"><div class="art-label">NIGHT CITY / A POSSIBLE FUTURE<br>ORIGINAL SPECULATIVE CITY STUDY</div><svg viewBox="0 0 620 470" preserveAspectRatio="xMidYMid slice"><defs><linearGradient id="sun" x2="0" y2="1"><stop stop-color="#ff7859"/><stop offset="1" stop-color="#f3329a"/></linearGradient><pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="#d85d89" stroke-opacity=".13"/></pattern></defs><rect width="620" height="470" fill="url(#grid)"/><circle cx="360" cy="200" r="125" fill="url(#sun)"/><path d="M200 205H510M200 220H510M200 243H510M200 265H510M200 280H510" stroke="#301d32" stroke-width="5"/><path d="M0 350L620 140M20 410L620 220" stroke="#e9fa60" stroke-opacity=".35"/>${buildings}<path d="M296 80V440H340V135H323V100Z" fill="#111521" stroke="#68d7d3" stroke-width="1"/><path d="M309 120V399M314 125V400" stroke="#ff439a"/><path d="M0 435H620" stroke="#5ce9e0"/><path d="M280 470L390 310L450 470" stroke="#f94995" fill="#14151c"/><path d="M340 470L390 340" stroke="#e9fa60" stroke-dasharray="12 16"/></svg><div class="art-bottom"><span>THE CITY IS NOT FINISHED.</span><span>REWRITE IT.</span></div></div>`;}
function home(){return `<section class="hero"><div><div class="eyebrow">A civic rebellion / An open experiment</div><h1>Who owns<br>the <em>future?</em></h1><p class="lead">Night City was built on a promise.<br>We’re here to examine the fine print.</p><p>An unofficial field guide to power, autonomy, and the city that could have been. Read the history. Change the variables. Imagine something worth living in.</p><div class="hero-actions"><button class="primary" data-go="sovereignty">Enter the experiment</button><button class="secondary" data-go="files">Open the archive</button></div><div class="fine">NO QUEST OUTCOMES. NO ENDINGS. NO FUTURE-GAME SPOILERS.</div></div>${cityArt()}</section><div class="ticker"><span>TECHNOLOGY SHOULD EXPAND HUMAN SOVEREIGNTY.</span><span>NOT REPLACE IT.</span><span>QUESTION EVERY SYSTEM.</span></div><div class="section-head"><h2>Pick up the signal.</h2><span>THREE WAYS INTO THE PROTOCOL</span></div><section class="grid3"><article class="card">${tag('canon','Fictional canon')}<h3>The dream. The fracture.</h3><p>Trace Richard Night’s ambition and ask what happens when a city’s institutions depend on its founder.</p><button class="link-button" data-go="files">Read the Richard Night Files</button></article><article class="card">${tag('interpretation','Interactive thought experiment')}<h3>Freedom has a budget.</h3><p>Put 100 civic credits to work. Every promise competes for resources. There is no perfect allocation.</p><button class="link-button" data-go="sovereignty">Test a different settlement</button></article><article class="card">${tag('speculation','Speculative design')}<h3>Another city is possible.</h3><p>Housing, transit, energy, public space. Build a proposal and confront the institutions it would need.</p><button class="link-button" data-go="reborn">Imagine Night City Reborn</button></article></section><div class="section-head"><h2>The manifesto</h2><span>EDITORIAL / NOT CANON</span></div><section class="two-col"><div><h2>Power should be<br>answerable to people.</h2><p>“Sovereignpunk” is our editorial invitation: use technology to increase the ability to live, organize, refuse and participate. Neither a corporate logo nor a public seal guarantees freedom.</p></div><div><p>We ask who can make decisions, who can challenge them, and who absorbs the costs. We value the right to exit alongside the capacity to act together. We test institutions, not just intentions.</p><p>Night City is a fictional case study, not evidence about real communities. A beautiful skyline cannot tell us whether a city is just.</p></div></section>`;}
const timeline=[
 ['1994','A city begins','Coronado City is founded through Richard Night’s planned-city project, backed by corporate investment.','A city can be independent of a nation while dependent on its financiers. Who gets a seat at the founding table?'],
 ['1998','The founder is gone','Richard Night is murdered. The city is renamed Night City in his memory.','Founder-led institutions face a succession problem. Could distributed authority have made the project less fragile?'],
 ['2000s','Power fills the vacuum','Organized crime and corporate power compete to shape the city after Night’s death.','When formal authority cannot protect residents, other institutions sell protection. Who can hold those institutions accountable?'],
 ['2077','The promise, unresolved','The game’s setting presents a spectacular metropolis marked by corporate dominance and deep inequality. No plot events are included here.','Legal autonomy is not the same as everyday freedom. Test that distinction in the Sovereignty Experiment.']
];
function files(){return intro('canon','Archive / institutional memory','Richard Night files.','An ideal city. A vulnerable founding bargain. Select a moment to separate what the fiction says from the questions we bring to it.')+`<div class="two-col"><div class="time-list" aria-label="Timeline events">${timeline.map((t,i)=>`<button data-year="${i}" class="${timelineIndex===i?'active':''}" aria-pressed="${timelineIndex===i}"><b>${t[0]}</b>${t[1]}</button>`).join('')}</div><article class="panel" aria-live="polite"><span class="eyebrow">Archive record</span><div class="big-year">${timeline[timelineIndex][0]}</div><h2>${timeline[timelineIndex][1]}</h2>${tag('canon','Fictional canon · paraphrase')}<p style="margin-top:18px">${timeline[timelineIndex][2]}</p><a class="source-link" href="${sources.history}" target="_blank" rel="noopener">Source: Night City history / community wiki (may contain spoilers)</a><hr style="border:0;border-top:1px solid #30323b;margin:24px 0">${tag('interpretation')}<p style="margin-top:18px">${timeline[timelineIndex][3]}</p><button data-go="sovereignty">Explore the institutional trade-offs</button></article></div><div class="notice">Scope: a deliberately selective, spoiler-light timeline. It is not a complete chronology. “Night” is the character’s canonical surname. Historical lore is summarized through the community reference; the political analysis is original editorial interpretation.</div>`;}
const labels=['Housing & basic services','Shared infrastructure','Civic voice & oversight','Enterprise & production'];
function sovereignty(){return intro('interpretation','Lab / scarce resources, competing promises','Freedom has a budget.','Allocate 100 civic credits. More capacity, more access and more autonomy do not automatically arrive together. Explore the assumptions behind every score.')+`<div class="two-col"><section class="panel"><div class="budget"><div class="mono">UNALLOCATED<br><small>CIVIC CREDITS</small></div><strong id="remaining"></strong></div><div class="pills"><button data-preset="balanced">Balanced</button><button data-preset="commons">Commons first</button><button data-preset="growth">Growth first</button></div>${labels.map((l,i)=>`<div class="control"><label for="a${i}">${l}<output id="av${i}"></output></label><input id="a${i}" type="range" min="0" max="100" step="1" value="${allocations[i]}" data-allocation="${i}"></div>`).join('')}<p style="font-size:14px">A slider stops at the available budget. Reduce another allocation to free up credits.</p><label class="check-row"><input id="shock" type="checkbox" ${shock?'checked':''}> Apply a supply disruption (20-point illustrative shock)</label><button id="allocation-reset">Reset allocation</button></section><section class="panel"><div class="eyebrow">Scenario readout / illustrative indices</div><div id="metrics" aria-live="polite"></div><p id="tradeoff" class="notice"></p><p>Scores are dimensionless indices from 0–100. They encode editorial choices; they do not measure a real city or prove a political system is superior.</p><button id="export-budget">Download scenario</button><div id="budget-status" class="save-status" role="status"></div><details><summary>Inspect the model and its limits</summary><p>H = housing, C = shared infrastructure, V = civic voice, E = enterprise. S = 0 normally, 20 under disruption. Each score is rounded and clamped to [0,100].</p><pre>Access = 20 + 1.25H + 0.5C − 0.7S
Autonomy = 15 + 1.4V + 0.65C − 0.25E
Capacity = 20 + 1.4E + 0.45C − 0.9S
Resilience = 10 + 1.8 min(H,C,V,E) + 0.65C − 0.5S</pre><p>Unspent credits remain unspent; they confer no resilience bonus. Spending has immediate linear effects, except the balance term in resilience. No prices, taxes, debt, population, corruption, time delays or distribution within groups are modeled. Weights are invented for exploration, not calibrated research.</p></details><details><summary>Research connection: governing shared resources</summary><p>Ostrom’s work examines how people organize governance of shared resources. It motivates our questions about participation and oversight; it does not validate these formulas.</p><a href="${sources.ostrom}" target="_blank" rel="noopener">Read the Nobel committee’s 2009 research summary (PDF)</a></details></section></div>`;}
function updateBudget(){const m=ProtocolModel.evaluate(allocations,shock);$('#remaining').textContent=m.reserve;allocations.forEach((v,i)=>{$('#av'+i).textContent=v;$('#a'+i).value=v;});$('#metrics').innerHTML=Object.entries(m).filter(([k])=>k!=='reserve').map(([k,v])=>`<div class="metric"><header><span>${k[0].toUpperCase()+k.slice(1)}</span><b>${v}<small style="font-size:12px;color:#a6a8b4"> / 100</small></b></header><div class="bar"><i style="width:${v}%"></i></div></div>`).join('');const low=allocations.indexOf(Math.min(...allocations));$('#tradeoff').textContent=`Your smallest commitment is ${labels[low].toLowerCase()}. What would residents lose if this remained underfunded? ${shock?'The disruption reduces access, capacity and resilience; voice is unchanged by assumption.':''}`;}
function circuitPage(){return intro('interpretation','Circuit economics / the feedback question','When systems oscillate.','Change damping, response strength and the initial shock. Watch an abstract system overshoot, settle or ring. Then question what this analogy leaves out.')+`<div class="two-col"><section class="panel">${[['damping','Damping',0,2,.05],['feedback','Response strength',.2,3,.1],['shock','Initial shock',.2,2,.1]].map(([k,l,min,max,step])=>`<div class="control"><label for="c-${k}">${l}<output id="cv-${k}">${circuit[k]}</output></label><input id="c-${k}" data-circuit="${k}" type="range" min="${min}" max="${max}" step="${step}" value="${circuit[k]}"></div>`).join('')}<div class="pills"><button data-circuit-preset="ring">Persistent ringing</button><button data-circuit-preset="settle">Fast settling</button><button data-circuit-preset="slow">Sluggish return</button></div><button id="circuit-reset">Reset experiment</button><div class="notice">A circuit-inspired mathematical analogy, not a macroeconomic forecast. No policy recommendation follows from the curve.</div></section><section class="panel"><div class="eyebrow">System response / deviation from equilibrium</div><svg class="scope" id="scope" viewBox="0 0 600 280" role="img" aria-labelledby="scope-title scope-description"><title id="scope-title">Damped oscillator response</title><desc id="scope-description"></desc><g stroke="#263c43" stroke-width="1">${[30,85,140,195,250].map(y=>`<path d="M35 ${y}H590"/>`).join('')}${[35,146,257,368,479,590].map(x=>`<path d="M${x} 20V260"/>`).join('')}</g><g fill="#9aadb5" font-family="monospace" font-size="12"><text x="3" y="34">+2</text><text x="12" y="144">0</text><text x="3" y="254">−2</text></g><path id="wave" fill="none" stroke="#5ce9e0" stroke-width="2.5"/></svg><div class="chart-labels"><span>0</span><span>MODEL TIME (ARBITRARY UNITS)</span><span>24</span></div><div id="circuit-status" class="chart-status" aria-live="polite"></div><p style="margin-top:18px">More damping dissipates motion. Too much can slow the return. Stronger response can increase the frequency of oscillation. Neither parameter is a real-world policy lever.</p><details><summary>Equation, analogy and evidence</summary><pre>x″ + 2dx′ + kx = 0
x(0) = initial shock; x′(0) = 0
d = damping; k = response strength
Semi-implicit Euler integration; step = 0.04</pre><p>This is an unforced damped oscillator, mathematically analogous to a simple RLC circuit. x is abstract deviation, not GDP. Electrical voltage/current and economic incentives/flows are only metaphors here. Human expectations, institutions and inequality are absent.</p>${tag('research')}<p>MONIAC demonstrates a historical use of physical analogies for economics. It was hydraulic, not electrical, and is not the model implemented above.</p><a href="${sources.moniac}" target="_blank" rel="noopener">Science Museum: analogue computing and MONIAC</a><p>Reading slot: your economics-and-electricity book is not yet identified. Add its title, page references and proposed mapping before making book-specific claims.</p></details></section></div>`;}
function updateCircuit(){Object.entries(circuit).forEach(([k,v])=>{$('#cv-'+k).textContent=Number(v).toFixed(2);$('#c-'+k).value=v;});const pts=ProtocolModel.oscillate(circuit.damping,circuit.feedback,circuit.shock);$('#wave').setAttribute('d',pts.map((p,i)=>`${i?'L':'M'}${(35+p.t/24*555).toFixed(2)},${(140-p.x*55).toFixed(2)}`).join(' '));const regime=circuit.damping===0?'Undamped · oscillations persist':circuit.damping<Math.sqrt(circuit.feedback)?'Underdamped · overshoot and decay':Math.abs(circuit.damping-Math.sqrt(circuit.feedback))<.02?'Near critical damping · fast return':'Overdamped · gradual return';$('#circuit-status').textContent=regime;$('#scope-description').textContent=`${regime}. Initial deviation ${circuit.shock}; final deviation ${pts.at(-1).x.toFixed(3)} at time 24.`;}
const lore=[
 ['Watson','district','Markets, dense neighborhoods and industrial remnants share the northern city.','Urban texture','A useful lens: who benefits when an industrial economy is restructured?'],
 ['Westbrook','district','Japantown’s nightlife and wealthy enclaves sit within the same district.','Consumption & status','A useful lens: how does prestige shape who feels welcome in public space?'],
 ['City Center','district','Corporate towers define the city’s concentrated business core.','Corporate power','A useful lens: who controls the spaces that appear publicly accessible?'],
 ['Heywood','district','Residential neighborhoods reveal sharp differences in wealth and opportunity.','Community & inequality','A useful lens: a neighborhood is more than the faction associated with it.'],
 ['Santo Domingo','district','An industrial district shaped by production and infrastructure.','Labor & infrastructure','A useful lens: who carries the environmental costs of the city’s economy?'],
 ['Pacifica','district','An unfinished resort vision leaves a landscape of abandoned investment.','Uneven development','A useful lens: what responsibilities survive when an investor leaves?'],
 ['Maelstrom','faction','A gang associated with extreme cybernetic modification.','Gang / public premise','Interpretation: bodily transformation can coexist with coercive power.'],
 ['Tyger Claws','faction','A gang closely associated with the city’s nightlife economy.','Gang / public premise','Interpretation: control of leisure can also be control of labor and territory.'],
 ['Valentinos','faction','A gang with a strong identity around loyalty, honor and community ties.','Gang / public premise','Interpretation: belonging does not remove the need for accountability.'],
 ['6th Street','faction','A gang with a pronounced patriotic and military identity.','Gang / public premise','Interpretation: claims of protection deserve scrutiny whoever makes them.'],
 ['The Mox','faction','A group associated with protecting sex workers and other vulnerable people.','Gang / public premise','Interpretation: mutual defense raises questions about reach and inclusion.'],
 ['Voodoo Boys','faction','A gang known for netrunning and an association with Pacifica.','Gang / public premise','Interpretation: access to networks can become a form of political power.'],
 ['Animals','faction','A gang recognized for physical enhancement and muscle-for-hire work.','Gang / public premise','Interpretation: the body becomes labor, equipment and a site of investment.'],
 ['Scavengers','faction','Predatory crews associated with stealing cyberware from victims.','Crews / public premise','Interpretation: a market in valuable implants can create violent incentives.']
];
function street(){return intro('canon','Street intelligence / context without plot','Know the city.','A compact atlas of six districts and eight factions. Setting descriptions only: no missions, character fates, endings, expansion storylines or future-game claims.')+`<div class="search-row"><label for="lore-search">Find a signal</label><input id="lore-search" type="search" placeholder="Search districts or factions…" value="${loreSearch.replaceAll('&','&amp;').replaceAll('"','&quot;').replaceAll('<','&lt;')}"><div class="pills" style="margin:0">${['all','district','faction'].map(v=>`<button data-filter="${v}" class="${loreFilter===v?'active':''}" aria-pressed="${loreFilter===v}">${v==='all'?'All records':v==='district'?'Districts':'Factions'}</button>`).join('')}</div></div><label><input type="checkbox" id="extended" ${extended?'checked':''}> Show editorial context (still no plot spoilers)</label><p class="notice">Spoiler policy: only broad setting premises appear here. External sources may include spoilers; opening them leaves this protection. This selection is an introduction, not an exhaustive lore encyclopedia.</p><p id="lore-count" class="mono" role="status"></p><section id="lore-results" class="lore-grid"></section>`;}
function updateLore(){const records=lore.filter(r=>(loreFilter==='all'||r[1]===loreFilter)&&r.join(' ').toLowerCase().includes(loreSearch.toLowerCase()));$('#lore-count').textContent=`${records.length} records found`;$('#lore-results').innerHTML=records.map(r=>`<article class="card"><span class="district">${r[3].toUpperCase()}</span><h3>${r[0]}</h3>${tag('canon','Fictional canon · summary')}<p style="margin-top:14px">${r[2]}</p>${extended?`${tag('interpretation')}<p style="margin-top:12px">${r[4]}</p>`:''}<a class="source-link" href="${r[1]==='district'?sources.districts:sources.gangs}" target="_blank" rel="noopener">${r[1]==='district'?'CDPR city guide':'PC Gamer faction guide'} · external / spoilers possible</a></article>`).join('')||'<p class="empty">No matching records. Try a district name, or clear the search.</p>';}
function reborn(){return intro('speculation','Alternative futures / a civic design desk','Night City, reborn.','What if sovereignty were built into the ordinary systems of daily life? Assemble a 100-credit neighborhood proposal. Nothing here is canonical or a prediction.')+`<div class="two-col"><section class="panel"><div class="budget"><div class="mono">PROPOSAL BUDGET</div><strong id="plan-budget"></strong></div>${planItems.map((p,i)=>`<label class="check-row"><input type="checkbox" data-plan="${i}" ${plan[i]?'checked':''}><span>${p[0]} <b class="mono" style="color:var(--acid)">${p[1]} cr</b><small>${p[2]}</small></span></label>`).join('')}<div id="plan-status" class="save-status" role="status"></div><div class="pills"><button id="plan-save">Save on this device</button><button id="plan-export">Download proposal</button><button id="plan-reset">Reset</button></div></section><section class="panel"><div class="eyebrow">Neighborhood schematic / not geographic</div><div id="plan-map" class="plan-map"></div><h2 style="margin-top:32px">Buildings need institutions.</h2><p id="plan-description"></p><div class="notice">Costs are invented, one-time comparison units. Land, operations, displacement, labor and material constraints would require real local study. An unchecked block is an unfunded proposal, not a claim that an existing service should be removed.</div><h3>The questions that survive the rendering</h3><p>Who owns the land? Who can veto displacement? Who maintains the system ten years later? How can residents remove decision-makers? A proposal is unfinished until these questions have answers.</p><details><summary>Research connection / where to go next</summary>${tag('research')}<p>Ostrom’s work invites investigation of rules, collective organization and shared resources. Our design translates those questions into a fictional neighborhood; the particular buildings and costs are speculative.</p><a href="${sources.ostrom}" target="_blank" rel="noopener">Research summary: economic governance and the commons</a></details></section></div>`;}
function updatePlan(){const spent=plan.reduce((s,v,i)=>s+(v?planItems[i][1]:0),0);$('#plan-budget').textContent=`${spent}/100`;$('#plan-map').innerHTML=planItems.map((p,i)=>`<div class="block ${plan[i]?'enabled':''}">${p[0]}<span class="skip">${plan[i]?'funded':'unfunded'}</span></div>`).join('');$('#plan-description').textContent=plan.some(Boolean)?`Selected priorities: ${planItems.filter((p,i)=>plan[i]).map(p=>p[0].toLowerCase()).join(', ')}. ${100-spent} credits remain. ${plan[4]?'The assembly adds a forum for oversight, but representation still needs rules.':'No civic assembly is funded. How will residents hold the project accountable?'}`:'No interventions selected. Choose a first commitment and describe who it serves.';document.querySelectorAll('[data-plan]').forEach(el=>el.checked=plan[+el.dataset.plan]);}
function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function render(){let route=location.hash.slice(1)||'home';if(!tabs.some(([k])=>k===route))route='home';$('#navigation').innerHTML=tabs.map(([k,l])=>`<a href="#${k}" ${k===route?'aria-current="page"':''}>${l}</a>`).join('');$('#main').innerHTML=({home,files,sovereignty,circuit:circuitPage,street,reborn}[route])();if(route==='sovereignty')updateBudget();if(route==='circuit')updateCircuit();if(route==='street')updateLore();if(route==='reborn')updatePlan();document.title=`${tabs.find(t=>t[0]===route)[1]} — Night City Sovereignty Protocol`;}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;const d=el.dataset;if(d.go)location.hash=d.go;if(d.year!==undefined){timelineIndex=+d.year;render();document.querySelector(`[data-year="${timelineIndex}"]`).focus();}if(d.preset){allocations={balanced:[25,25,25,25],commons:[30,35,25,10],growth:[15,20,10,55]}[d.preset];updateBudget();}if(el.id==='allocation-reset'){allocations=[25,25,25,25];shock=0;$('#shock').checked=false;updateBudget();}if(el.id==='export-budget'){download('sovereignty-scenario.json',{version:'0.1',kind:'illustrative-model',labels,allocations,shock,results:ProtocolModel.evaluate(allocations,shock)});$('#budget-status').textContent='Scenario download prepared.';}if(d.circuitPreset){circuit={ring:{damping:0,feedback:1,shock:1},settle:{damping:1,feedback:1,shock:1},slow:{damping:2,feedback:.5,shock:1}}[d.circuitPreset];updateCircuit();}if(el.id==='circuit-reset'){circuit={damping:.35,feedback:1,shock:1};updateCircuit();}if(d.filter){loreFilter=d.filter;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===loreFilter);b.setAttribute('aria-pressed',b.dataset.filter===loreFilter);});updateLore();}if(el.id==='plan-save'){try{localStorage.setItem('ncsp-plan-v1',JSON.stringify(plan));$('#plan-status').textContent='Proposal saved on this browser.';}catch{$('#plan-status').textContent='Browser storage unavailable. Download the proposal instead.';}}if(el.id==='plan-export'){download('night-city-reborn.json',{version:'0.1',kind:'speculative-design',budget:100,selected:planItems.filter((p,i)=>plan[i]).map(([name,cost,tradeoff])=>({name,cost,tradeoff}))});$('#plan-status').textContent='Proposal download prepared.';}if(el.id==='plan-reset'){plan=[true,true,false,false,false,false];updatePlan();$('#plan-status').textContent='Reset to starter proposal. Save to replace the stored version.';}});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.allocation!==undefined){allocations=ProtocolModel.allocate(allocations,+el.dataset.allocation,+el.value);updateBudget();}if(el.dataset.circuit){circuit[el.dataset.circuit]=+el.value;updateCircuit();}if(el.id==='lore-search'){loreSearch=el.value;updateLore();}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='shock'){shock=el.checked?20:0;updateBudget();}if(el.id==='extended'){extended=el.checked;updateLore();}if(el.dataset.plan!==undefined){const i=+el.dataset.plan;const spent=plan.reduce((s,v,j)=>s+(v?planItems[j][1]:0),0);if(el.checked&&spent+planItems[i][1]>100){el.checked=false;$('#plan-status').textContent='That exceeds 100 credits. Uncheck another intervention first.';}else{plan[i]=el.checked;$('#plan-status').textContent='Proposal updated. Save to keep it on this device.';}updatePlan();}});
$('#source-body').innerHTML=`<p style="margin-top:24px">Four labels keep different kinds of knowledge separate.</p><p>${tag('canon','Fictional canon')} Published setting material, summarized through the sources below.<br><br>${tag('research')} Real scholarship and historical context.<br><br>${tag('interpretation')} Our editorial questions and illustrative models.<br><br>${tag('speculation')} Proposed futures, not official lore.</p><h3>Source ledger</h3><ul><li><a href="${sources.history}" target="_blank" rel="noopener">Cyberpunk Wiki: Night City</a> — community secondary reference for the selected historical timeline. Underlying world: Cyberpunk by R. Talsorian Games and Cyberpunk 2077 by CD PROJEKT RED.</li><li><a href="${sources.districts}" target="_blank" rel="noopener">CD PROJEKT RED: Your Trip to Night City</a> — primary city guide for district atmosphere. District names also appear in the <a href="https://resources.cmon.com/Cyberpunk-2077-Rulebook.pdf" target="_blank" rel="noopener">licensed board-game rulebook</a>.</li><li><a href="${sources.gangs}" target="_blank" rel="noopener">PC Gamer: Cyberpunk 2077 gangs</a> — secondary source for broad faction premises. No plot outcomes are reproduced.</li><li><a href="${sources.ostrom}" target="_blank" rel="noopener">Nobel committee, 2009 research summary</a> — context on Ostrom and commons governance. Does not support the invented numeric weights.</li><li><a href="${sources.moniac}" target="_blank" rel="noopener">Science Museum: Back to the Future of Computing</a> — historical analogue-computing context. MONIAC was hydraulic; our oscillator is a separate teaching analogy.</li></ul><div class="notice">External sources can contain spoilers. This site excludes quest outcomes, character fates, endings, expansion plots and future-game speculation. Reviewed for this edition: 24 November 2026.</div><h3>Reading notebook / open slot</h3><p>The referenced economics book has not been identified. No text or ideas are attributed to an unnamed book. Future contributions should include title, author, edition, page, a short paraphrase and the limits of the analogy.</p><h3>Privacy & credits</h3><p>No accounts, analytics, external fonts or tracking scripts. Only the Reborn proposal is saved locally, when you choose Save. Use your browser’s site-data controls to erase it. The interface, abstract skyline and editorial prose are original. All models run in your browser. No endorsement by the Cyberpunk rights holders is implied.</p>`;
$('#sources-open').addEventListener('click',()=>$('#sources').showModal());$('#sources-close').addEventListener('click',()=>$('#sources').close());
try{const saved=JSON.parse(localStorage.getItem('ncsp-plan-v1'));if(Array.isArray(saved)&&saved.length===6&&saved.every(v=>typeof v==='boolean')&&saved.reduce((s,v,i)=>s+(v?planItems[i][1]:0),0)<=100)plan=saved;}catch{}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});});render();
